import React, { useState } from 'react';
import { Header } from './components/header';
import { UserCard } from './components/usercard';
import { BadgeList } from './components/badgelist';
import { RankingTable } from './components/rankingtable';
import "./estilos.css";

export default function App() {
  // Estado do usuário
  const [user, setUser] = useState({
    name: 'Carlos Silva',
    xp: 450,
    level: 3,
    badges: [
      { id: 1, title: 'Guardião da Senha', icon: '🛡️', description: 'Criou uma senha forte e ativou 2FA.' },
      { id: 2, title: 'Caçador de Phishing', icon: '🎣', description: 'Identificou e reportou um e-mail suspeito.' }
    ]
  });

  // Estado do ranking
  const [ranking, setRanking] = useState([
    { rank: 1, name: 'Ana Souza', xp: 820 },
    { rank: 2, name: 'Carlos Silva (Você)', xp: 450, isUser: true },
    { rank: 3, name: 'Mariana Lima', xp: 390 },
    { rank: 4, name: 'João Pedro', xp: 250 }
  ]);

  // Função para simular o ganho de XP em tempo real
  const handleAddXp = () => {
    setUser((prev) => ({ ...prev, xp: prev.xp + 50 }));
  };

  return (
    <div className="app-container">
      <Header />
      <UserCard user={user} onAddXp={handleAddXp} />
      <BadgeList badges={user.badges} />
      <RankingTable ranking={ranking} />
    </div>
  );
}
